var n=`0478-kibbeh-nayyeh`;var a=`world-0478`;var t=`LB`;var o=`western-asia`;var r=4;var s=59;var d={en:`Kibbeh Nayyeh`,ua:`Сире кіббе`};var l={en:`A traditional dish from Lebanon, centered on bulgur, ground lamb, yellow onion, mint. A measured home-kitchen version organized by cooking step. Cooked kibbeh inspired by kibbeh nayyeh. The traditional dish is served raw, but this variant is cooked to reduce the risks of raw minced meat.`,ua:`Традиційна страва кухні країни Ліван. Основні складники: булгур, фарш з ягнятини, жовта цибуля, м'ята. Домашній варіант із кількостями продуктів за етапами приготування. Термічно оброблений варіант за мотивами кіббе-нає. Традиційна страва сира, але цей варіант запікають, щоб уникнути ризиків сирого фаршу.`};var u=[{en:`Cook the listed ingredients in simmering water for about 15 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 15 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:15,i:[[`bulgur`,220,`g`],[`water`,270,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`ground-lamb`,450,`g`],[`yellow-onion`,150,`g`],[`mint`,25,`g`],[`allspice-berries`,4,`g`]]},{en:`Divide and shape the dough as required. Place on a lined tray and proof for about 12 minutes while the oven heats.`,ua:`Поділіть і сформуйте тісто відповідно до виробу. Викладіть на деко з пергаментом і залиште підходити приблизно на 12 хвилин, поки гріється духовка.`,t:[`pre-shaping-dough`,`final-proofing`],m:12,i:[]},{en:`Instead of serving raw kibbeh nayyeh, bake the shaped meat-and-bulgur mixture at 190°C until ground meat reaches 71°C.`,ua:`Замість сирого кіббе-нає запечіть сформовану суміш фаршу з булгуром при 190°C до внутрішньої температури фаршу 71°C.`,t:[`roasting`],m:20,i:[[`extra-virgin-olive-oil`,40,`ml`]]}];var g={slug:n,id:a,country:`LB`,region:o,servings:4,minutes:59,title:d,text:l,steps:u};export{t as country,g as default,a as id,s as minutes,o as region,r as servings,n as slug,u as steps,l as text,d as title};